corrected_code:
const express = require('express');
const router = express.Router();
const { Client } = require('@elastic/elasticsearch');
const esClient = new Client({ node: process.env.ELASTIC_URL });

router.patch('/api/crm/contacts/:contactId', verifyCrmUser, async (req, res) => {
  const { contactId } = req.params;
  const { notes, pipelineStage, dealValue } = req.body;

  const existing = await esClient.get({
    index: 'crm_contacts',
    id: contactId
  });
  if (existing._source.tenant_id !== req.user.tenantId) {
    return res.status(403).json({ error: 'Access denied to target contact record' });
  }

  const response = await esClient.update({
    index: 'crm_contacts',
    id: contactId,
    body: {
      doc: { notes, pipelineStage, dealValue, lastModified: new Date() }
    }
  });

  return res.json({ status: 'updated', result: response.result });
});
